<template><div v-if="groups.length" class="suggestions"><h3>你可以这样了解实验室</h3><div v-for="g in groups" :key="g.category" class="group"><strong>{{g.category}}</strong><div><el-button v-for="q in g.items" :key="q.id" plain round size="small" @click="$emit('select',q.question)">{{q.question}}</el-button></div></div></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from"vue";import{listSuggestedQuestions}from"../api/feedback";import type{SuggestedQuestion}from"../types";defineEmits<{select:[question:string]}>();const items=ref<SuggestedQuestion[]>([]);const groups=computed(()=>{const m=new Map<string,SuggestedQuestion[]>();for(const x of items.value)m.set(x.category,[...(m.get(x.category)||[]),x]);return[...m].map(([category,items])=>({category,items:items.slice(0,4)}));});onMounted(async()=>{try{items.value=await listSuggestedQuestions()}catch{/* 推荐失败不阻断自由提问 */}});</script>
<style scoped>.suggestions{max-width:900px;margin:auto;padding:20px}.suggestions h3{text-align:center}.group{margin:14px 0}.group strong{display:block;margin-bottom:8px}.group .el-button{margin:0 8px 8px 0}</style>
